from pathlib import Path
import re

p = Path('index.html')
text = p.read_text(encoding='utf-8')

new_block = r'''function breakdownForm(b={}){const t=b.id?(b.time||''):nowLocalTime();return `<div class="form-grid">${deviceSearchField(b.deviceId||'')}<div class="field"><label>Datum melding *</label><input name="date" type="date" required value="${b.date||todayISO()}"><div class="muted" style="font-size:11px;margin-top:4px">Bij nieuwe registratie automatisch vandaag; aanpasbaar.</div></div><div class="field"><label>Uur melding</label><input name="time" type="time" required value="${t}"><div class="muted" style="font-size:11px;margin-top:4px">Bij nieuwe registratie automatisch het huidige uur; aanpasbaar.</div></div><div class="field"><label>Prioriteit</label><select name="priority">${['Laag','Normaal','Hoog','Kritiek'].map(x=>`<option ${b.priority===x||(!b.priority&&x==='Normaal')?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Status</label><select name="status">${['Open','In behandeling','Opgelost'].map(x=>`<option ${b.status===x||(!b.status&&x==='Open')?'selected':''}>${x}</option>`).join('')}</select></div><div class="field full"><label>Probleem / melding *</label><textarea name="issue" required>${esc(b.issue||'')}</textarea></div><div class="field full"><label>Diagnose</label><textarea name="diagnosis">${esc(b.diagnosis||'')}</textarea></div><div class="field full"><label>Oplossing / uitgevoerde werken</label><textarea name="solution">${esc(b.solution||'')}</textarea></div><div class="field"><label>Technieker</label><input name="technician" value="${esc(b.technician||'')}"></div><div class="field"><label>Werkuren</label><input name="hours" type="number" min="0" step="0.25" value="${b.hours??''}"></div>${usageBuilder(b.usedParts||[],true)}</div>`}
function breakdownLocationGroups(){return maintenanceLocationGroups()}
function breakdownLocationMatches(query){const q=normalizeSearch(query);return breakdownLocationGroups().filter(g=>!q||normalizeSearch(g.label).includes(q)).slice(0,12)}
function breakdownBatchForm(){const t=nowLocalTime();return `<div class="form-grid"><div class="field full"><label>Locatie *</label><div class="maintenance-location-autocomplete"><input id="breakdownLocationSearch" type="search" required placeholder="Typ een locatie…" autocomplete="off"><input id="breakdownLocationKey" name="locationKey" type="hidden"><div id="breakdownLocationSuggestions" class="maintenance-location-suggestions"></div></div><div id="breakdownLocationCount" class="muted" style="font-size:11px;margin-top:4px">Typ een deel van de locatie. De zoeklijst wordt automatisch korter.</div></div><div class="field"><label>Datum melding *</label><input name="date" type="date" required value="${todayISO()}"></div><div class="field"><label>Uur melding *</label><input name="time" type="time" required value="${t}"></div><div class="field full"><label>Technieker</label><input name="technician" placeholder="Naam technieker"></div><div class="field full"><div class="maintenance-location-head"><div><div class="section-title" style="margin-bottom:3px">Toestellen op deze locatie</div><div class="muted" style="font-size:11px">Selecteer de toestellen waarop een depannage werd uitgevoerd. Probleem, diagnose, oplossing en onderdelen worden per toestel geregistreerd.</div></div><button type="button" class="btn small" id="breakdownSelectAll" style="display:none">Alles selecteren</button></div><div id="breakdownLocationDevices" class="maintenance-machine-list"><div class="empty" style="padding:24px">Zoek en kies eerst een locatie om de actieve toestellen te tonen.</div></div></div></div>`}
function breakdownMachineCardHtml(d){const machine=[d.brand,d.model].filter(Boolean).join(' ')||'Geen toestelomschrijving',loc=deviceLocationAt(d)||d.location||'';return `<div class="maintenance-machine-card breakdown-machine-card" data-breakdown-device="${esc(d.id)}"><label class="maintenance-machine-title"><input type="checkbox" class="breakdown-machine-check"><span><strong>${esc(d.assetCode||d.model||'Toestel')}</strong><small>${esc(machine)}${d.serial?' · S/N '+esc(d.serial):''}${loc?' · '+esc(loc):''}</small></span></label><div class="maintenance-machine-fields"><div class="field"><label>Prioriteit</label><select class="breakdown-machine-priority" disabled>${['Laag','Normaal','Hoog','Kritiek'].map(x=>`<option ${x==='Normaal'?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Status</label><select class="breakdown-machine-status" disabled>${['Open','In behandeling','Opgelost'].map(x=>`<option ${x==='Open'?'selected':''}>${x}</option>`).join('')}</select></div><div class="field" style="grid-column:1/-1"><label>Probleem / melding *</label><textarea class="breakdown-machine-issue" disabled placeholder="Wat is er aan de hand met dit toestel?"></textarea></div><div class="field" style="grid-column:1/-1"><label>Diagnose</label><textarea class="breakdown-machine-diagnosis" disabled placeholder="Vastgestelde oorzaak / diagnose"></textarea></div><div class="field" style="grid-column:1/-1"><label>Oplossing / uitgevoerde werken</label><textarea class="breakdown-machine-solution" disabled placeholder="Wat werd uitgevoerd?"></textarea></div><div class="field"><label>Werkuren</label><input class="breakdown-machine-hours" type="number" min="0" step="0.25" disabled></div><div class="maintenance-machine-usage"><div class="section-title">Gebruikte onderdelen</div><div class="muted" style="font-size:11px;margin:-4px 0 7px">Onderdelen worden uitsluitend aan dit toestel gekoppeld.</div><div class="usage-list breakdown-device-usage-list" data-searchable="1">${usageRowHtml({partId:'',qty:1},true)}</div><button type="button" class="btn small breakdown-add-usage" disabled style="margin-top:8px">+ Onderdeelregel</button></div></div></div>`}
function setBreakdownMachineEnabled(card,enabled){if(!card)return;card.classList.toggle('selected',enabled);card.querySelectorAll('.breakdown-machine-priority,.breakdown-machine-status,.breakdown-machine-issue,.breakdown-machine-diagnosis,.breakdown-machine-solution,.breakdown-machine-hours,.breakdown-add-usage,.usage-search,.usage-qty,.remove-line').forEach(el=>el.disabled=!enabled)}
function initBreakdownLocationForm(){const input=$('#breakdownLocationSearch'),hidden=$('#breakdownLocationKey'),suggestions=$('#breakdownLocationSuggestions'),box=$('#breakdownLocationDevices'),count=$('#breakdownLocationCount'),selectAll=$('#breakdownSelectAll');if(!input||!hidden||!suggestions||!box)return;const hideLocations=()=>suggestions.classList.remove('show');const hidePartSuggestions=row=>{const menu=row?.querySelector('.usage-suggestions');if(menu)menu.classList.remove('show')};const renderDevices=group=>{if(!group){box.innerHTML='<div class="empty" style="padding:24px">Zoek en kies eerst een locatie om de actieve toestellen te tonen.</div>';if(count)count.textContent='Typ een deel van de locatie. De zoeklijst wordt automatisch korter.';if(selectAll)selectAll.style.display='none';return}box.innerHTML=group.devices.map(breakdownMachineCardHtml).join('');box.querySelectorAll('.breakdown-machine-card').forEach(card=>setBreakdownMachineEnabled(card,false));if(count)count.textContent=`${group.devices.length} actief toestel${group.devices.length===1?'':'len'} op ${group.label}`;if(selectAll){selectAll.style.display='';selectAll.textContent='Alles selecteren'}};const renderLocations=()=>{const matches=breakdownLocationMatches(input.value);suggestions.innerHTML=matches.length?matches.map(g=>`<button type="button" class="maintenance-location-suggestion" data-location-key="${esc(g.key)}"><strong>${esc(g.label)}</strong><small>${g.devices.length} actief toestel${g.devices.length===1?'':'len'}</small></button>`).join(''):'<div class="maintenance-location-empty">Geen locatie gevonden.</div>';suggestions.classList.add('show')};input.oninput=()=>{hidden.value='';input.setCustomValidity('Kies een locatie uit de zoeklijst.');renderDevices(null);renderLocations()};input.onfocus=renderLocations;input.onkeydown=e=>{if(e.key==='Escape'){hideLocations();return}if(e.key==='Enter'&&suggestions.classList.contains('show')){const first=suggestions.querySelector('.maintenance-location-suggestion');if(first){e.preventDefault();first.click()}}};suggestions.onclick=e=>{const choice=e.target.closest('.maintenance-location-suggestion');if(!choice)return;const group=breakdownLocationGroups().find(g=>g.key===choice.dataset.locationKey);if(!group)return;hidden.value=group.key;input.value=group.label;input.setCustomValidity('');hideLocations();renderDevices(group)};input.onfocusout=()=>setTimeout(hideLocations,140);if(selectAll)selectAll.onclick=()=>{const cards=[...box.querySelectorAll('.breakdown-machine-card')],allSelected=cards.length&&cards.every(c=>c.querySelector('.breakdown-machine-check')?.checked);cards.forEach(card=>{const check=card.querySelector('.breakdown-machine-check');if(check){check.checked=!allSelected;setBreakdownMachineEnabled(card,!allSelected)}});selectAll.textContent=allSelected?'Alles selecteren':'Alles uitvinken'};box.onchange=e=>{if(e.target.classList.contains('breakdown-machine-check')){const card=e.target.closest('.breakdown-machine-card');setBreakdownMachineEnabled(card,e.target.checked);if(selectAll){const cards=[...box.querySelectorAll('.breakdown-machine-card')];selectAll.textContent=cards.length&&cards.every(c=>c.querySelector('.breakdown-machine-check')?.checked)?'Alles uitvinken':'Alles selecteren'}}};box.onclick=e=>{const suggestion=e.target.closest('.usage-suggestion');if(suggestion){const row=suggestion.closest('.usage-row'),part=state.parts.find(p=>p.id===suggestion.dataset.partId),partInput=row?.querySelector('.usage-search'),partHidden=row?.querySelector('.usage-part');if(part&&partInput&&partHidden){partInput.value=usagePartDisplay(part);partHidden.value=part.id;hidePartSuggestions(row)}return}const add=e.target.closest('.breakdown-add-usage');if(add){const list=add.closest('.maintenance-machine-usage')?.querySelector('.breakdown-device-usage-list');if(list){const div=document.createElement('div');div.innerHTML=usageRowHtml({partId:'',qty:1},true);const row=div.firstElementChild;if(row){list.appendChild(row);row.querySelector('.usage-search')?.focus()}}return}if(e.target.classList.contains('remove-line'))e.target.closest('.usage-row')?.remove()};box.oninput=e=>{if(!e.target.classList.contains('usage-search'))return;const row=e.target.closest('.usage-row'),menu=row?.querySelector('.usage-suggestions'),partHidden=row?.querySelector('.usage-part');if(partHidden)partHidden.value='';const q=e.target.value.trim();if(!menu)return;if(!q){menu.classList.remove('show');menu.innerHTML='';return}menu.innerHTML=usageSuggestionsHtml(q);menu.classList.add('show')};box.onkeydown=e=>{if(!e.target.classList.contains('usage-search'))return;const row=e.target.closest('.usage-row'),menu=row?.querySelector('.usage-suggestions');if(e.key==='Escape'){hidePartSuggestions(row);return}if(e.key==='Enter'&&menu?.classList.contains('show')){const first=menu.querySelector('.usage-suggestion');if(first){e.preventDefault();first.click()}}};box.onfocusout=e=>{if(e.target.classList.contains('usage-search'))setTimeout(()=>hidePartSuggestions(e.target.closest('.usage-row')),140)};input.setCustomValidity('Kies een locatie uit de zoeklijst.');renderDevices(null)}
function breakdownBatchSelectedItems(){return $$('.breakdown-machine-card').filter(card=>card.querySelector('.breakdown-machine-check')?.checked).map(card=>({deviceId:card.dataset.breakdownDevice,priority:card.querySelector('.breakdown-machine-priority')?.value||'Normaal',status:card.querySelector('.breakdown-machine-status')?.value||'Open',issue:card.querySelector('.breakdown-machine-issue')?.value.trim()||'',diagnosis:card.querySelector('.breakdown-machine-diagnosis')?.value.trim()||'',solution:card.querySelector('.breakdown-machine-solution')?.value.trim()||'',hours:Number(card.querySelector('.breakdown-machine-hours')?.value||0),usedParts:[...card.querySelectorAll('.breakdown-device-usage-list .usage-row')].map(row=>({partId:row.querySelector('.usage-part')?.value||'',qty:Number(row.querySelector('.usage-qty')?.value||1)})).filter(u=>u.partId&&u.qty>0)}))}
function checkBreakdownBatchUsage(items){const totals={};items.forEach(item=>(item.usedParts||[]).forEach(u=>totals[u.partId]=(totals[u.partId]||0)+Number(u.qty||0)));for(const [id,qty] of Object.entries(totals)){const p=state.parts.find(x=>x.id===id);if(p&&Number(p.stock||0)<qty)return `Onvoldoende voorraad voor ${p.artNr} (${p.stock} beschikbaar, ${qty} nodig voor deze depannageronde).`}return ''}
async function applyBreakdownBatchUsage(items){return applyMaintenanceBatchUsage(items)}
function openBreakdown(id){if(id){const old=state.breakdowns.find(b=>b.id===id);if(!old)return;showModal('Depannage bijwerken',breakdownForm(old),'Opslaan',async fd=>{const usage=collectUsage(),err=checkUsage(usage,old.usedParts||[]);if(err){alert(err);return}const b={...old,deviceId:val(fd,'deviceId'),date:val(fd,'date'),time:val(fd,'time'),priority:val(fd,'priority'),status:val(fd,'status'),issue:val(fd,'issue'),diagnosis:val(fd,'diagnosis'),solution:val(fd,'solution'),technician:val(fd,'technician'),hours:Number(fd.get('hours')||0),usedParts:usage,updatedAt:new Date().toISOString()};await applyUsage(usage,old.usedParts||[]);await put('breakdowns',b);closeModal();await refresh();toast('Depannage opgeslagen')});setTimeout(()=>{initDeviceSearch(old.deviceId||'');initUsageControls()},0);return}const groups=breakdownLocationGroups();if(!groups.length){toast('Geen actieve toestellen met een locatie gevonden');return}showModal('Depannage per locatie',breakdownBatchForm(),'Depannage registreren',async fd=>{const items=breakdownBatchSelectedItems();if(!items.length){alert('Selecteer minstens één toestel waarop een depannage is uitgevoerd.');return}const noIssue=items.find(item=>!item.issue);if(noIssue){const d=state.devices.find(x=>x.id===noIssue.deviceId);alert(`Vul een probleem / melding in voor ${d?.assetCode||d?.model||'het geselecteerde toestel'}.`);return}const err=checkBreakdownBatchUsage(items);if(err){alert(err);return}const date=val(fd,'date'),time=val(fd,'time'),technician=val(fd,'technician'),now=new Date().toISOString();const records=items.map(item=>({id:uid('brk'),deviceId:item.deviceId,date,time,priority:item.priority,status:item.status,issue:item.issue,diagnosis:item.diagnosis,solution:item.solution,technician,hours:item.hours,usedParts:item.usedParts,createdAt:now,updatedAt:now}));await applyBreakdownBatchUsage(items);await putMany('breakdowns',records);closeModal();await refresh();toast(`${records.length} depannageregistratie${records.length===1?'':'s'} opgeslagen`)});setTimeout(initBreakdownLocationForm,0)}'''

text, n = re.subn(r'function breakdownForm\(b=\{\}\)\{.*?\}\nfunction openBreakdown\(id\)\{.*?\}\nfunction showDeviceHistory', new_block + '\nfunction showDeviceHistory', text, count=1, flags=re.S)
if n != 1:
    raise SystemExit('breakdownForm/openBreakdown blok niet gevonden')

p.write_text(text, encoding='utf-8')

sw = Path('sw.js')
sw_text = sw.read_text(encoding='utf-8')
sw_text = re.sub(r"machinepark-v[0-9.]+-[^']+", 'machinepark-v1.58-breakdown-location-search', sw_text, count=1)
sw.write_text(sw_text, encoding='utf-8')

test = Path('tests/build-smoke.test.mjs')
t = test.read_text(encoding='utf-8')
needle = "    'data-view=\"breakdowns\"',\n"
replacement = "    'data-view=\"breakdowns\"',\n    'id=\"breakdownLocationSearch\"',\n    'id=\"breakdownLocationSuggestions\"',\n    'breakdownLocationMatches',\n    'breakdownBatchSelectedItems',\n"
if "id=\"breakdownLocationSearch\"" not in t:
    t = t.replace(needle, replacement)
t = re.sub(r"machinepark-v[0-9.]+-[^']+", 'machinepark-v1.58-breakdown-location-search', t)
test.write_text(t, encoding='utf-8')

validator = Path('scripts/build-machinepark.py')
v = validator.read_text(encoding='utf-8')
v = v.replace('"depannage navigatie": "data-view=\\"breakdowns\\"",', '"depannage navigatie": "data-view=\\"breakdowns\\"",\n    "locatiegerichte depannage": "id=\\"breakdownLocationSearch\\"",\n    "depannage per toestel": "breakdown-machine-card",')
v = re.sub(r"machinepark-v[0-9.]+-[^\"]+", 'machinepark-v1.58-breakdown-location-search', v)
validator.write_text(v, encoding='utf-8')
